//! Reader for `fixtures/object-raster-asset-resources/oracle.txt` (generated by
//! tools/gen.js: Node-zlib PNG byte strings with their authored straight-RGBA
//! pixels, plus the verbatim baseline `naturalSize` outcomes) and the shared
//! builders of the L06-E tests. See HANDOFF.md for provenance.
use super::{retain_core, AssetPixels, AssetPixelsError, Request, RetainedAsset};
use crate::object_codec::{
    decode_allocated_project, encoded_wire_test, ImageAssetLimits, PngWorkspace, ProjectEnvelope,
};
use crate::object_document::{AssetId, AssetInventory, AssetKind, AssetRecord, AssetSource};
use crate::revision::{ImageResourceBudget, ObjectSnapshot};
use serde_json::Value;
use std::sync::Arc;

pub(crate) const ORACLE: &str = include_str!("fixtures/object-raster-asset-resources/oracle.txt");

pub(crate) fn rows(kind: &str) -> Vec<Value> {
    ORACLE
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .map(|line| serde_json::from_str::<Value>(line).expect("oracle row is JSON"))
        .filter(|row| row["kind"] == kind)
        .collect()
}
pub(crate) fn row(name: &str) -> Value {
    rows("png")
        .into_iter()
        .find(|row| row["name"] == name)
        .unwrap_or_else(|| panic!("oracle row {name}"))
}
pub(crate) fn unhex(text: &str) -> Vec<u8> {
    assert!(text.len() % 2 == 0, "odd hex length");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digit pair"))
        .collect()
}
pub(crate) fn png(name: &str) -> Vec<u8> {
    unhex(row(name)["hex"].as_str().expect("hex field"))
}
/// The pixels the PNG was authored from: an explicit list or one flat colour.
pub(crate) fn expected_rgba(row: &Value) -> Vec<u8> {
    if let Some(list) = row["rgba"].as_array() {
        return list.iter().map(|v| v.as_u64().unwrap() as u8).collect();
    }
    let fill: Vec<u8> = row["fill"]
        .as_array()
        .expect("rgba or fill")
        .iter()
        .map(|v| v.as_u64().unwrap() as u8)
        .collect();
    let pixels = row["w"].as_u64().unwrap() * row["h"].as_u64().unwrap();
    (0..pixels).flat_map(|_| fill.clone()).collect()
}

/// Generous decoder bounds that still admit every `ok` oracle row.
pub(crate) fn limits() -> ImageAssetLimits {
    ImageAssetLimits::new(1 << 20, 1 << 20, 4 << 20, 512, 512).unwrap()
}
/// A private quota domain so `used()` is exact while other tests run.
pub(crate) fn budget() -> ImageResourceBudget {
    ImageResourceBudget::isolated(8 << 20).unwrap()
}
/// Exactly what `charged_png_workspace` reserves for the inflate workspace.
pub(crate) fn workspace_bytes() -> usize {
    std::mem::size_of::<PngWorkspace>()
}
pub(crate) fn never() -> bool {
    false
}

pub(crate) fn embedded(
    id: &str,
    media_type: &str,
    kind: AssetKind,
    allocation: Arc<Vec<u8>>,
) -> Arc<AssetRecord> {
    let limit = allocation.capacity();
    let source = AssetSource::admitted_embedded(media_type.to_string(), allocation, limit)
        .expect("embedded source");
    Arc::new(
        AssetRecord::new(
            AssetId::new(id.to_string()).expect("asset id"),
            format!("{id}.bin"),
            kind,
            source,
        )
        .expect("asset record"),
    )
}
pub(crate) fn linked(id: &str, kind: AssetKind, locator: &str) -> Arc<AssetRecord> {
    let source = AssetSource::linked(locator.to_string(), 4096).expect("linked source");
    Arc::new(
        AssetRecord::new(
            AssetId::new(id.to_string()).expect("asset id"),
            format!("{id}.bin"),
            kind,
            source,
        )
        .expect("asset record"),
    )
}
pub(crate) fn inventory(records: Vec<Arc<AssetRecord>>) -> AssetInventory {
    AssetInventory::new(records, Vec::new(), 1024, 0).expect("inventory")
}
/// "first" and "second" share ONE encoded allocation; "third" holds equal
/// bytes in its own allocation (the owner ledger dedups by pointer only).
pub(crate) fn shared_trio(bytes: &[u8]) -> Vec<Arc<AssetRecord>> {
    let shared = Arc::new(bytes.to_vec());
    vec![
        embedded("first", "image/png", AssetKind::Image, Arc::clone(&shared)),
        embedded("second", "image/png", AssetKind::Image, shared),
        embedded(
            "third",
            "image/png",
            AssetKind::Image,
            Arc::new(bytes.to_vec()),
        ),
    ]
}

pub(crate) fn project_without_assets() -> ProjectEnvelope {
    let wire = serde_json::to_vec(&encoded_wire_test::wire()).unwrap();
    decode_allocated_project(&wire, encoded_wire_test::limits(), |n| Ok(vec![0; n])).unwrap()
}
pub(crate) fn project(records: Vec<Arc<AssetRecord>>) -> ProjectEnvelope {
    project_without_assets().with_asset_inventory(Some(inventory(records)))
}
pub(crate) fn snapshot(records: Vec<Arc<AssetRecord>>) -> ObjectSnapshot {
    ObjectSnapshot::from_admitted_project("assets".into(), project(records))
        .expect("owner admits the project")
}

pub(super) fn request<'a>(
    snapshot: &'a ObjectSnapshot,
    asset_id: &'a str,
    held: &'a [AssetPixels],
) -> Request<'a> {
    Request {
        snapshot,
        asset_id,
        limits: limits(),
        held,
        cancel: &never,
    }
}
/// The production composition (charge allocator, `Arc` carrier) on a private budget.
pub(crate) fn retain_in(
    budget: &ImageResourceBudget,
    snapshot: &ObjectSnapshot,
    asset_id: &str,
    held: &[AssetPixels],
) -> Result<AssetPixels, AssetPixelsError> {
    retain_core(
        &request(snapshot, asset_id, held),
        budget,
        |charge| charge.allocate(),
        |retained| Ok(AssetPixels(Arc::new(retained))),
    )
}

/// A snapshot holding one embedded PNG image named "a", read from the oracle row.
pub(crate) fn one_image(name: &str) -> ObjectSnapshot {
    snapshot(vec![embedded(
        "a",
        "image/png",
        AssetKind::Image,
        Arc::new(png(name)),
    )])
}
/// The production carrier as a `wrap` argument.
pub(super) fn arc_pixels(retained: RetainedAsset) -> Result<AssetPixels, AssetPixelsError> {
    Ok(AssetPixels(Arc::new(retained)))
}
